fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = i32::MIN; // Initialize to the smallest possible i32 value

    for &num in &numbers {
        if num > current_max {
            current_max = num; // Update current maximum
        }
        result.push(current_max); // Append the current maximum to the result
    }

    result
}